// Corpus generator (section 3). Deterministic: (seed, size) fully determines file
// bytes; tenant only enters the manifest.
import { createHash } from "node:crypto";
import { deflateSync } from "node:zlib";
import fs from "node:fs";
import path from "node:path";

export type FileEntry = {
  order: number;
  path: string;
  extension: string;
  bytes: number;
  sha256: string;
  role: "normal" | "duplicate" | "edge_case";
  duplicate_of: string | null;
  edge_case: string | null;
  expected_outcome: "annotated" | "empty_content" | "decode_failed";
  expects_annotation: boolean;
};

export type Manifest = {
  corpus_id: string;
  arguments: { seed: number; size: number; tenant: string };
  totals: Record<string, number>;
  edge_cases: { path: string; edge_case: string; expected_outcome: string }[];
  files: FileEntry[];
  digest: string;
};

const EXTS = ["txt", "json", "csv", "png"];
const EMPTY_IDX = 7; // 0-based; both < 50 so every allowed size has them
const DECODE_IDX = 13;
const WORDS = "alpha bravo charlie delta echo foxtrot golf hotel india juliet kilo lima mike november oscar papa".split(" ");

function rng(seed: number, size: number, index: number): () => number {
  const h = createHash("sha256").update(`${seed}:${size}:${index}`).digest();
  let s = h.readUInt32BE(0) || 1;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const crcTable = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf: Buffer): number {
  let c = -1;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function pngChunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function makePng(r: () => number): Buffer {
  const w = 8 + Math.floor(r() * 9);
  const h = 8 + Math.floor(r() * 9);
  const raw = Buffer.alloc(h * (1 + w * 3));
  for (let y = 0; y < h; y++) {
    const off = y * (1 + w * 3);
    raw[off] = 0; // filter: none
    for (let x = 0; x < w; x++) {
      raw[off + 1 + x * 3] = Math.floor(r() * 256);
      raw[off + 2 + x * 3] = Math.floor(r() * 256);
      raw[off + 3 + x * 3] = Math.floor(r() * 256);
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // truecolour
  // level 0 (stored) keeps the deflate stream identical across zlib builds
  const idat = deflateSync(raw, { level: 0 });
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    pngChunk("IHDR", ihdr),
    pngChunk("IDAT", idat),
    pngChunk("IEND", Buffer.alloc(0)),
  ]);
}

function words(r: () => number, n: number): string {
  return Array.from({ length: n }, () => WORDS[Math.floor(r() * WORDS.length)]).join(" ");
}

function makeContent(ext: string, index: number, seed: number, size: number): Buffer {
  const r = rng(seed, size, index);
  if (ext === "png") return makePng(r);
  if (ext === "json") {
    const obj = {
      id: index,
      title: words(r, 4),
      tags: Array.from({ length: 1 + Math.floor(r() * 4) }, () => words(r, 1)),
      score: Math.floor(r() * 1000),
      body: words(r, 20 + Math.floor(r() * 30)),
    };
    return Buffer.from(JSON.stringify(obj, null, 2) + "\n", "utf8");
  }
  if (ext === "csv") {
    const rows = 3 + Math.floor(r() * 12);
    const lines = ["id,name,value"];
    for (let i = 0; i < rows; i++) lines.push(`${i},${words(r, 1)},${Math.floor(r() * 500)}`);
    return Buffer.from(lines.join("\n") + "\n", "utf8");
  }
  const paras = 2 + Math.floor(r() * 5);
  return Buffer.from(
    Array.from({ length: paras }, () => words(r, 20 + Math.floor(r() * 40))).join("\n\n") + "\n",
    "utf8",
  );
}

function canonical(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonical).join(",")}]`;
  if (v && typeof v === "object") {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`)
      .join(",")}}`;
  }
  return JSON.stringify(v ?? null);
}

/** Builds manifest + file bytes in memory. Pure function of the arguments. */
export function buildCorpus(seed: number, size: number, tenant: string) {
  const files: FileEntry[] = [];
  const bytesByPath = new Map<string, Buffer>();
  const pathByIndex = new Map<number, string>();

  for (let i = 0; i < size; i++) {
    let ext = EXTS[i % EXTS.length];
    let role: FileEntry["role"] = "normal";
    let edge: string | null = null;
    let rel: string;
    let data: Buffer;
    let dupOf: string | null = null;

    if (i === EMPTY_IDX) {
      ext = "txt";
      edge = "empty_content";
      role = "edge_case";
      rel = "edge/empty.txt";
      data = Buffer.alloc(0);
    } else if (i === DECODE_IDX) {
      ext = "json";
      edge = "decode_failed";
      role = "edge_case";
      rel = "edge/malformed.json";
      data = makePng(rng(seed, size, i)); // PNG bytes behind a .json extension
    } else if (i >= 15 && i % 10 === 5) {
      // ~1 in 10 items is a byte-for-byte duplicate of an earlier item, same extension
      const src = i - 4;
      const srcPath = pathByIndex.get(src)!;
      ext = path.extname(srcPath).slice(1);
      role = "duplicate";
      dupOf = srcPath;
      data = bytesByPath.get(srcPath)!;
      rel =
        i % 20 === 5
          ? `dupes/${path.basename(srcPath)}` // same name, different directory
          : `dupes/copy_${String(i + 1).padStart(4, "0")}.${ext}`; // different name
    } else {
      rel = `${ext}/item_${String(i + 1).padStart(4, "0")}.${ext}`;
      data = makeContent(ext, i, seed, size);
    }

    bytesByPath.set(rel, data);
    pathByIndex.set(i, rel);
    const expected: FileEntry["expected_outcome"] =
      edge === "empty_content" ? "empty_content" : edge === "decode_failed" ? "decode_failed" : "annotated";
    files.push({
      order: i + 1,
      path: rel,
      extension: ext,
      bytes: data.length,
      sha256: createHash("sha256").update(data).digest("hex"),
      role,
      duplicate_of: dupOf,
      edge_case: edge,
      expected_outcome: expected,
      expects_annotation: edge === null,
    });
  }

  const totals: Record<string, number> = { items: size };
  for (const f of files) {
    totals[`ext_${f.extension}`] = (totals[`ext_${f.extension}`] ?? 0) + 1;
    totals[`role_${f.role}`] = (totals[`role_${f.role}`] ?? 0) + 1;
  }

  const base = {
    corpus_id: createHash("sha256").update(`${seed}:${size}:${tenant}`).digest("hex").slice(0, 16),
    arguments: { seed, size, tenant },
    totals,
    edge_cases: files
      .filter((f) => f.edge_case)
      .map((f) => ({ path: f.path, edge_case: f.edge_case!, expected_outcome: f.expected_outcome })),
    files,
  };
  const manifest: Manifest = { ...base, digest: createHash("sha256").update(canonical(base)).digest("hex") };
  return { manifest, bytesByPath };
}

export function writeCorpus(dir: string, seed: number, size: number, tenant: string, force: boolean) {
  if (fs.existsSync(dir) && fs.readdirSync(dir).length > 0) {
    if (!force) throw new Error(`${dir} is not empty (use --force)`);
    fs.rmSync(dir, { recursive: true });
  }
  const { manifest, bytesByPath } = buildCorpus(seed, size, tenant);
  for (const [rel, data] of bytesByPath) {
    const abs = path.join(dir, "files", rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, data);
  }
  fs.writeFileSync(path.join(dir, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
  return manifest;
}

/** Re-derives the corpus from the manifest's own arguments and diffs every byte. */
export function verifyCorpus(dir: string) {
  const manifest: Manifest = JSON.parse(fs.readFileSync(path.join(dir, "manifest.json"), "utf8"));
  const { seed, size, tenant } = manifest.arguments;
  const { manifest: expected, bytesByPath } = buildCorpus(seed, size, tenant);
  const problems: string[] = [];
  if (expected.digest !== manifest.digest) problems.push("manifest digest differs");
  const onDisk = new Set<string>();
  const walk = (d: string, prefix = "") => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      if (e.isDirectory()) walk(path.join(d, e.name), `${prefix}${e.name}/`);
      else onDisk.add(prefix + e.name);
    }
  };
  walk(path.join(dir, "files"));
  for (const [rel, want] of bytesByPath) {
    onDisk.delete(rel);
    const abs = path.join(dir, "files", rel);
    if (!fs.existsSync(abs)) problems.push(`missing ${rel}`);
    else if (!fs.readFileSync(abs).equals(want)) problems.push(`bytes differ ${rel}`);
  }
  for (const extra of onDisk) problems.push(`unexpected file ${extra}`);
  return { ok: problems.length === 0, problems, corpus_id: manifest.corpus_id, checked: bytesByPath.size };
}

// Annotation stub (section 5). Single process, single server worker: counters and
// the failure schedule are per-process state.
import http from "node:http";
import { createHash } from "node:crypto";

type Config = {
  latency_mode: "fixed" | "jitter";
  latency_ms: number;
  latency_jitter_min_ms: number;
  latency_jitter_max_ms: number;
  latency_seed: number;
  failure_every_n: number;
  failure_status: number;
  in_flight_capacity: number;
};

const DEFAULTS: Config = {
  latency_mode: "fixed",
  latency_ms: 150,
  latency_jitter_min_ms: 50,
  latency_jitter_max_ms: 250,
  latency_seed: 20260803,
  failure_every_n: 7,
  failure_status: 500,
  in_flight_capacity: 2,
};

function fromEnv(): Config {
  const c = { ...DEFAULTS };
  for (const k of Object.keys(DEFAULTS) as (keyof Config)[]) {
    const v = process.env[`STUB_${k.toUpperCase()}`];
    if (v === undefined) continue;
    (c as Record<string, unknown>)[k] = k === "latency_mode" ? v : Number(v);
  }
  return c;
}

export function createStub(config: Config = fromEnv()) {
  let cfg = { ...config };
  let billed = 0,
    serverErrors = 0,
    overCapacity = 0,
    inFlight = 0,
    maxInFlight = 0,
    latencyStep = 0;

  const latency = (): number => {
    if (cfg.latency_mode !== "jitter") return cfg.latency_ms;
    // deterministic jitter sequence: replays identically after /v1/reset
    const h = createHash("sha256").update(`${cfg.latency_seed}:${latencyStep++}`).digest();
    const span = Math.max(0, cfg.latency_jitter_max_ms - cfg.latency_jitter_min_ms);
    return cfg.latency_jitter_min_ms + (h.readUInt32BE(0) % (span + 1));
  };

  const stats = () => ({
    billed_calls: billed,
    current_in_flight: inFlight,
    max_in_flight: maxInFlight,
    server_error_calls: serverErrors,
    over_capacity_calls: overCapacity,
    config: cfg,
  });

  const send = (res: http.ServerResponse, status: number, body: unknown) => {
    const b = Buffer.from(JSON.stringify(body));
    res.writeHead(status, { "content-type": "application/json", "content-length": b.length });
    res.end(b);
  };

  const readBody = (req: http.IncomingMessage) =>
    new Promise<string>((resolve, reject) => {
      const chunks: Buffer[] = [];
      req.on("data", (c) => chunks.push(c));
      req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
      req.on("error", reject);
    });

  const server = http.createServer(async (req, res) => {
    const url = (req.url ?? "/").split("?")[0];

    if (req.method === "GET" && url === "/healthz") return send(res, 200, { status: "ok" });
    if (req.method === "GET" && url === "/v1/stats") return send(res, 200, stats());

    if (req.method === "POST" && url === "/v1/reset") {
      const raw = await readBody(req);
      if (raw.trim()) {
        let patch: Record<string, unknown>;
        try {
          patch = JSON.parse(raw);
        } catch {
          return send(res, 400, { error: { code: "invalid_request", message: "body is not JSON" } });
        }
        for (const [k, v] of Object.entries(patch)) {
          if (!(k in DEFAULTS)) return send(res, 400, { error: { code: "invalid_request", message: `unknown field ${k}` } });
          (cfg as Record<string, unknown>)[k] = k === "latency_mode" ? v : Number(v);
        }
      }
      billed = serverErrors = overCapacity = maxInFlight = latencyStep = 0;
      return send(res, 200, { status: "reset", config: cfg });
    }

    if (req.method === "POST" && url === "/v1/annotate") {
      const raw = await readBody(req);
      let body: Record<string, unknown>;
      try {
        body = JSON.parse(raw);
      } catch {
        return send(res, 400, { error: { code: "invalid_request", message: "body is not JSON" } });
      }
      const keys = Object.keys(body ?? {});
      if (keys.length !== 1 || keys[0] !== "content_b64" || typeof body.content_b64 !== "string")
        return send(res, 400, { error: { code: "invalid_request", message: "content_b64 is the only accepted field" } });

      // billed before the outcome is chosen (EXT-REQ-4)
      billed += 1;
      const myBilled = billed;

      if (inFlight >= cfg.in_flight_capacity) {
        overCapacity += 1;
        return send(res, 429, { error: { code: "over_capacity", message: "in-flight limit reached" } });
      }

      inFlight += 1;
      maxInFlight = Math.max(maxInFlight, inFlight);
      const wait = latency();
      const fail = cfg.failure_every_n > 0 && myBilled % cfg.failure_every_n === 0;
      let released = false;
      const release = () => {
        if (!released) {
          released = true;
          inFlight -= 1;
        }
      };
      res.on("close", release); // caller disconnect frees the slot

      await new Promise((r) => setTimeout(r, wait));
      if (res.destroyed) return release();

      if (fail) {
        serverErrors += 1;
        release();
        return send(res, cfg.failure_status, { error: { code: "server_error", message: "failure schedule fired" } });
      }

      const bytes = Buffer.from(body.content_b64 as string, "base64");
      const sha = createHash("sha256").update(bytes).digest("hex");
      release();
      return send(res, 200, {
        annotation: {
          sha256: sha,
          // deterministic function of the request bytes alone (EXT-REQ-5)
          label: ["document", "record", "table", "image", "note"][bytes.length ? bytes[0] % 5 : 0],
          confidence: Number((((parseInt(sha.slice(0, 4), 16) % 1000) / 1000) * 0.5 + 0.5).toFixed(3)),
          tokens: Math.min(4096, bytes.length),
        },
        meta: { billed_call: myBilled, latency_ms: wait },
      });
    }

    return send(res, 404, { error: { code: "not_found", message: url } });
  });

  return server;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const i = process.argv.indexOf("--port");
  const port = i >= 0 ? Number(process.argv[i + 1]) : Number(process.env.PORT ?? 8080);
  createStub().listen(port, () => console.log(`stub listening on ${port}`));
}

import { Pool } from "pg";

export const DB_URL = process.env.INTAKE_DB_URL ?? "postgres://intake:intake@127.0.0.1:55432/intake";
export const STUB_URL = process.env.STUB_URL ?? "http://127.0.0.1:8080";

let pool: Pool | null = null;
export function db(): Pool {
  if (!pool) pool = new Pool({ connectionString: DB_URL, max: 4 });
  return pool;
}

export async function closeDb() {
  if (pool) await pool.end();
  pool = null;
}

const SCHEMA = `
create table if not exists runs (
  run_id      text primary key,
  tenant      text not null,
  corpus_id   text not null,
  corpus_dir  text not null,
  item_count  int  not null,
  created_at  timestamptz not null default now()
);
create table if not exists items (
  item_id        text primary key,
  run_id         text not null references runs(run_id),
  tenant         text not null,
  corpus_id      text not null,
  source_path    text not null,
  abs_path       text not null,
  extension      text not null,
  declared_bytes int  not null,
  bytes          int,
  sha256         text,
  state          text not null,
  attempts       int  not null default 0,
  retries        int  not null default 0,
  annotate_calls int  not null default 0,
  error          jsonb,
  extracted_text text,
  annotation     jsonb,
  worker_id      text,
  lease_until    timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  terminal_at    timestamptz
);
create index if not exists items_claim_idx on items (state, lease_until);
create index if not exists items_run_idx   on items (run_id, state);
create index if not exists items_tenant_idx on items (tenant, item_id);
-- annotation reuse for repeated bytes, scoped per tenant so nothing crosses tenants
create table if not exists annotation_cache (
  tenant     text not null,
  sha256     text not null,
  annotation jsonb not null,
  created_at timestamptz not null default now(),
  primary key (tenant, sha256)
);
create table if not exists workers (
  worker_id  text primary key,
  pid        int not null,
  index      int not null,
  started_at timestamptz not null default now(),
  alive      boolean not null default true
);
`;

export async function initSchema() {
  await db().query(SCHEMA);
}

export const TERMINAL_STATES = ["annotated", "empty_content", "decode_failed", "annotation_failed", "unreadable"];

// Per-item processing (section 4) plus the stub-boundary retry policy (D-05).
import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import { PoolClient } from "pg";
import { db, STUB_URL } from "./db.js";

export const POLICY = {
  request_timeout_ms: 5000,
  max_attempts: 4, // 1 try + 3 retries per item-processing pass
  backoff_ms: [200, 400, 800],
  retryable_statuses: [429, 500, 502, 503, 504],
  lease_ms: 5000,
  heartbeat_ms: 1500,
  annotate_slots: Number(process.env.INTAKE_ANNOTATE_SLOTS ?? 2),
};

const SLOT_LOCK_NS = 918273;

/** Cluster-wide limiter: one Postgres advisory lock per stub in-flight slot, so the
 *  shared cap holds across all worker processes (REQ-2.2). */
async function withSlot<T>(lockClient: PoolClient, fn: () => Promise<T>): Promise<T> {
  for (;;) {
    for (let slot = 1; slot <= POLICY.annotate_slots; slot++) {
      const r = await lockClient.query("select pg_try_advisory_lock($1,$2) as got", [SLOT_LOCK_NS, slot]);
      if (r.rows[0].got) {
        try {
          return await fn();
        } finally {
          await lockClient.query("select pg_advisory_unlock($1,$2)", [SLOT_LOCK_NS, slot]);
        }
      }
    }
    await new Promise((r) => setTimeout(r, 25));
  }
}

type AnnotateResult =
  | { ok: true; annotation: unknown; calls: number; retries: number }
  | { ok: false; code: string; detail: string; calls: number; retries: number };

async function callStub(bytes: Buffer): Promise<{ status: number; body: any } | { status: 0; body: any }> {
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), POLICY.request_timeout_ms);
  try {
    const res = await fetch(`${STUB_URL}/v1/annotate`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ content_b64: bytes.toString("base64") }),
      signal: ac.signal,
    });
    return { status: res.status, body: await res.json().catch(() => null) };
  } catch (e) {
    return { status: 0, body: { error: { code: "transport_error", message: String(e) } } };
  } finally {
    clearTimeout(t);
  }
}

async function annotate(lockClient: PoolClient, bytes: Buffer): Promise<AnnotateResult> {
  let calls = 0;
  let retries = 0;
  let last = { code: "unknown", detail: "" };
  for (let attempt = 0; attempt < POLICY.max_attempts; attempt++) {
    if (attempt > 0) {
      retries++;
      await new Promise((r) => setTimeout(r, POLICY.backoff_ms[Math.min(attempt - 1, POLICY.backoff_ms.length - 1)]));
    }
    const res = await withSlot(lockClient, async () => {
      calls++;
      return callStub(bytes);
    });
    if (res.status === 200 && res.body?.annotation) return { ok: true, annotation: res.body.annotation, calls, retries };
    const code = res.body?.error?.code ?? `http_${res.status}`;
    last = { code, detail: JSON.stringify(res.body ?? null).slice(0, 300) };
    if (!POLICY.retryable_statuses.includes(res.status) && res.status !== 0) break; // 400 etc: not retryable
  }
  return { ok: false, code: last.code, detail: last.detail, calls, retries };
}

const TEXT_EXTS = new Set(["txt", "csv", "json"]);

function decodeUtf8(bytes: Buffer): string {
  const text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); // throws on invalid utf-8
  return text;
}

/** Extract text/metadata for one item; throws {code} style errors for decode failures. */
function extract(ext: string, bytes: Buffer): { text: string | null } {
  if (ext === "png") {
    const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    if (!bytes.subarray(0, 8).equals(sig)) throw { code: "decode_failed", detail: "not a PNG (bad signature)" };
    return { text: null }; // binary: no text carried by the declared type (ITEM-REQ-2)
  }
  if (!TEXT_EXTS.has(ext)) throw { code: "decode_failed", detail: `unsupported extension .${ext}` };
  let text: string;
  try {
    text = decodeUtf8(bytes);
  } catch {
    throw { code: "decode_failed", detail: "invalid utf-8 for declared text type" };
  }
  if (ext === "json") {
    try {
      JSON.parse(text);
    } catch (e) {
      throw { code: "decode_failed", detail: `json parse error: ${String(e).slice(0, 120)}` };
    }
  }
  if (ext === "csv") {
    const rows = text.split(/\r?\n/).filter((l) => l.length > 0);
    if (rows.length === 0) throw { code: "decode_failed", detail: "csv has no rows" };
    const cols = rows[0].split(",").length;
    if (rows.some((r) => r.split(",").length !== cols))
      throw { code: "decode_failed", detail: "csv rows have inconsistent column counts" };
  }
  return { text };
}

export async function processItem(lockClient: PoolClient, item: any, workerId: string, log: (s: string) => void) {
  const set = async (sql: string, params: unknown[]) =>
    db().query(`update items set updated_at=now(), ${sql} where item_id=$1`, [item.item_id, ...params]);
  const terminal = async (state: string, extra: string, params: unknown[]) =>
    set(`state=$${params.length + 2}, terminal_at=now(), lease_until=null${extra ? ", " + extra : ""}`, [
      ...params,
      state,
    ]);

  let bytes: Buffer;
  try {
    bytes = await fs.readFile(item.abs_path);
  } catch (e) {
    await terminal("unreadable", "error=$2", [{ code: "unreadable", detail: String(e).slice(0, 200) }]);
    return log(`${item.item_id} unreadable`);
  }

  const sha = createHash("sha256").update(bytes).digest("hex");
  await set("bytes=$2, sha256=$3", [bytes.length, sha]);

  if (bytes.length === 0) {
    // pre-annotation terminal error: no annotation request is issued (ITEM-REQ-4)
    await terminal("empty_content", "error=$2", [{ code: "empty_content", detail: "file has zero bytes" }]);
    return log(`${item.item_id} empty_content`);
  }

  let text: string | null;
  try {
    text = extract(item.extension, bytes).text;
  } catch (e: any) {
    await terminal("decode_failed", "error=$2", [{ code: e.code ?? "decode_failed", detail: e.detail ?? String(e) }]);
    return log(`${item.item_id} decode_failed`);
  }
  await set("extracted_text=$2", [text]);

  const cached = await db().query("select annotation from annotation_cache where tenant=$1 and sha256=$2", [
    item.tenant,
    sha,
  ]);
  if (cached.rowCount) {
    await terminal("annotated", "annotation=$2", [cached.rows[0].annotation]);
    return log(`${item.item_id} annotated (cache hit)`);
  }

  const r = await annotate(lockClient, bytes);
  await db().query("update items set annotate_calls=annotate_calls+$2, retries=retries+$3 where item_id=$1", [
    item.item_id,
    r.calls,
    r.retries,
  ]);
  if (!r.ok) {
    await terminal("annotation_failed", "error=$2", [
      { code: "annotation_failed", stub_error: r.code, detail: r.detail, calls: r.calls },
    ]);
    return log(`${item.item_id} annotation_failed (${r.code})`);
  }
  await db().query(
    "insert into annotation_cache (tenant, sha256, annotation) values ($1,$2,$3) on conflict do nothing",
    [item.tenant, sha, r.annotation],
  );
  await terminal("annotated", "annotation=$2", [r.annotation]);
  log(`${item.item_id} annotated`);
}

// One independently killable OS worker process (REQ-1.4, REQ-2.1).
// Ownership lives in Postgres: a claim is a lease, and an expired lease makes the
// item runnable again for any other worker (D-01).
import { db, initSchema, closeDb } from "./db.js";
import { POLICY, processItem } from "./pipeline.js";

const index = Number(process.argv[2] ?? 0);
const workerId = `w${index}-${process.pid}`;
const log = (s: string) => console.log(`${new Date().toISOString()} ${workerId} ${s}`);

const CLAIM = `
update items set state='processing', worker_id=$1, attempts=attempts+1,
       lease_until=now() + ($2::int * interval '1 millisecond'), updated_at=now()
where item_id = (
  select item_id from items
   where state='pending' or (state='processing' and lease_until < now())
   order by created_at, item_id
   limit 1 for update skip locked)
returning *`;

async function main() {
  await initSchema();
  const lockClient = await db().connect(); // dedicated session holding advisory slot locks
  await db().query(
    `insert into workers (worker_id, pid, worker_index, alive) values ($1,$2,$3,true)
     on conflict (worker_id) do update set alive=true`,
    [workerId, process.pid, index],
  );
  log(`up (pid ${process.pid})`);

  let stopping = false;
  const shutdown = async () => {
    stopping = true;
    await db().query("update workers set alive=false where worker_id=$1", [workerId]).catch(() => {});
    await closeDb().catch(() => {});
    process.exit(0);
  };
  process.on("SIGTERM", shutdown);
  process.on("SIGINT", shutdown);

  while (!stopping) {
    const r = await db().query(CLAIM, [workerId, POLICY.lease_ms]);
    if (!r.rowCount) {
      await new Promise((res) => setTimeout(res, 200));
      continue;
    }
    const item = r.rows[0];
    log(`claimed ${item.item_id} attempt ${item.attempts}`);
    const hb = setInterval(() => {
      db()
        .query(
          `update items set lease_until=now() + ($2::int * interval '1 millisecond')
             where item_id=$1 and worker_id=$3 and state='processing'`,
          [item.item_id, POLICY.lease_ms, workerId],
        )
        .catch(() => {});
    }, POLICY.heartbeat_ms);
    try {
      await processItem(lockClient, item, workerId, log);
    } catch (e) {
      log(`ERROR ${item.item_id} ${String(e)}`);
      // leave the lease to expire: another worker picks it up (D-01)
    } finally {
      clearInterval(hb);
    }
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

// Local environment lifecycle: Postgres (container), stub, workers (REQ-2.1).
import { spawn, execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { db, initSchema, STUB_URL } from "./db.js";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const RUN_DIR = path.join(ROOT, ".run");
const COMPOSE = ["compose", "-f", path.join(ROOT, "src/docker-compose.yml")];
const TSX = path.join(ROOT, "node_modules/.bin/tsx");

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const alive = (pid: number) => {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
};

function pidFile(name: string) {
  return path.join(RUN_DIR, `${name}.pid`);
}

function readPid(name: string): number | null {
  const f = pidFile(name);
  if (!fs.existsSync(f)) return null;
  const pid = Number(fs.readFileSync(f, "utf8").trim());
  return pid && alive(pid) ? pid : null;
}

function startDetached(name: string, args: string[], env: Record<string, string> = {}) {
  fs.mkdirSync(RUN_DIR, { recursive: true });
  const out = fs.openSync(path.join(RUN_DIR, `${name}.log`), "a");
  const child = spawn(TSX, args, {
    cwd: ROOT,
    detached: true,
    stdio: ["ignore", out, out],
    env: { ...process.env, ...env },
  });
  child.unref();
  fs.writeFileSync(pidFile(name), String(child.pid));
  return child.pid!;
}

async function stubHealthy() {
  try {
    const r = await fetch(`${STUB_URL}/healthz`, { signal: AbortSignal.timeout(500) });
    return r.ok;
  } catch {
    return false;
  }
}

async function dbReady() {
  try {
    await db().query("select 1");
    return true;
  } catch {
    return false;
  }
}

export async function up(workers: number) {
  const steps: string[] = [];

  execFileSync("docker", [...COMPOSE, "up", "-d"], { stdio: "inherit" });
  for (let i = 0; i < 60; i++) {
    if (await dbReady()) break;
    await sleep(1000);
  }
  if (!(await dbReady())) throw new Error("postgres did not become ready");
  await initSchema();
  steps.push("postgres ready");

  if (await stubHealthy()) steps.push("stub already running");
  else {
    const pid = startDetached("stub", ["src/stub.ts", "--port", "8080"]);
    for (let i = 0; i < 40; i++) {
      if (await stubHealthy()) break;
      await sleep(250);
    }
    if (!(await stubHealthy())) throw new Error("stub did not become healthy");
    steps.push(`stub started (pid ${pid}, port 8080)`);
  }

  const started: number[] = [];
  for (let i = 0; i < workers; i++) {
    if (readPid(`worker-${i}`)) continue;
    started.push(startDetached(`worker-${i}`, ["src/worker.ts", String(i)]));
  }
  // any worker beyond the requested count is stopped so `up` is idempotent per --workers
  for (let i = workers; i < 32; i++) {
    const pid = readPid(`worker-${i}`);
    if (pid) {
      try {
        process.kill(pid, "SIGTERM");
      } catch {}
      fs.rmSync(pidFile(`worker-${i}`), { force: true });
    }
  }
  steps.push(`workers: ${workers} requested, ${started.length} newly started`);
  return { ok: true, workers, steps };
}

export async function down() {
  const stopped: string[] = [];
  if (fs.existsSync(RUN_DIR)) {
    for (const f of fs.readdirSync(RUN_DIR).filter((f) => f.endsWith(".pid"))) {
      const name = f.replace(/\.pid$/, "");
      const pid = readPid(name);
      if (pid) {
        try {
          process.kill(pid, "SIGTERM");
          stopped.push(`${name}(${pid})`);
        } catch {}
      }
      fs.rmSync(path.join(RUN_DIR, f), { force: true });
    }
  }
  await sleep(500);
  execFileSync("docker", [...COMPOSE, "down", "-v"], { stdio: "inherit" });
  return { ok: true, stopped };
}

export async function liveWorkers() {
  const r = await db().query("select worker_id, pid, worker_index from workers where alive order by worker_index");
  return r.rows.filter((w) => alive(w.pid));
}

export async function killWorker(index?: number) {
  const live = await liveWorkers();
  const target = index === undefined ? live[0] : live.find((w) => w.worker_index === index);
  if (!target) throw new Error(`no live worker${index === undefined ? "" : ` with index ${index}`}`);
  const owned = await db().query(
    "select item_id, run_id, tenant, state from items where worker_id=$1 and terminal_at is null",
    [target.worker_id],
  );
  process.kill(target.pid, "SIGKILL"); // no supervisor: it stays dead
  await db().query("update workers set alive=false where worker_id=$1", [target.worker_id]);
  fs.rmSync(pidFile(`worker-${target.worker_index}`), { force: true });
  return {
    killed: { worker_id: target.worker_id, pid: target.pid, index: target.worker_index },
    owned_nonterminal_items: owned.rows,
    killed_at: new Date().toISOString(),
  };
}

export async function truncateState() {
  await initSchema();
  await db().query("truncate items, runs, annotation_cache");
}

export async function stubReset(patch: Record<string, unknown> = {}) {
  const r = await fetch(`${STUB_URL}/v1/reset`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(patch),
  });
  if (!r.ok) throw new Error(`stub reset failed: ${r.status}`);
  return r.json();
}

export async function stubStats() {
  const r = await fetch(`${STUB_URL}/v1/stats`);
  return r.json() as Promise<any>;
}

#!/usr/bin/env -S npx tsx
// Unified command interface (section 2a).
import fs from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";
import { writeCorpus, verifyCorpus, Manifest } from "./corpus.js";
import { db, closeDb, initSchema, TERMINAL_STATES } from "./db.js";
import { up, down, killWorker, liveWorkers } from "./env.js";
import { createStub } from "./stub.js";

const argv = process.argv.slice(2);
const cmd = argv[0];

function flag(name: string): string | undefined {
  const i = argv.indexOf(`--${name}`);
  return i >= 0 ? argv[i + 1] : undefined;
}
const has = (name: string) => argv.includes(`--${name}`);
function need(name: string): string {
  const v = flag(name);
  if (v === undefined) fail(`missing --${name}`);
  return v!;
}
function out(v: unknown) {
  console.log(JSON.stringify(v, null, 2));
}
function fail(msg: string): never {
  console.error(JSON.stringify({ error: msg }));
  process.exit(1);
}

const ITEM_COLS = `item_id, run_id, tenant, corpus_id, state, sha256, bytes, declared_bytes, source_path,
  extension, attempts, retries, annotate_calls, extracted_text, annotation, error, worker_id,
  created_at, updated_at, terminal_at`;

export async function submitCorpus(dir: string, tenant: string) {
  const manifest: Manifest = JSON.parse(fs.readFileSync(path.join(dir, "manifest.json"), "utf8"));
  const runId = `run_${Date.now().toString(36)}${randomBytes(3).toString("hex")}`;
  await initSchema();
  await db().query("insert into runs (run_id, tenant, corpus_id, corpus_dir, item_count) values ($1,$2,$3,$4,$5)", [
    runId,
    tenant,
    manifest.corpus_id,
    path.resolve(dir),
    manifest.files.length,
  ]);
  const ids = manifest.files.map((f) => `${runId}-i${String(f.order).padStart(4, "0")}`);
  await db().query(
    `insert into items (item_id, run_id, tenant, corpus_id, source_path, abs_path, extension, declared_bytes, state)
     select t.item_id, $2, $3, $4, t.source_path, t.abs_path, t.extension, t.declared_bytes, 'pending'
       from unnest($1::text[], $5::text[], $6::text[], $7::text[], $8::int[])
         as t(item_id, source_path, abs_path, extension, declared_bytes)`,
    [
      ids,
      runId,
      tenant,
      manifest.corpus_id,
      manifest.files.map((f) => f.path),
      manifest.files.map((f) => path.resolve(dir, "files", f.path)),
      manifest.files.map((f) => f.extension),
      manifest.files.map((f) => f.bytes),
    ],
  );
  return { run_id: runId, tenant, corpus_id: manifest.corpus_id, items: manifest.files.length };
}

export async function runStatus(runId: string) {
  const run = await db().query("select run_id, tenant, corpus_id, item_count from runs where run_id=$1", [runId]);
  if (!run.rowCount) fail(`run not found: ${runId}`);
  const rows = await db().query("select state, count(*)::int as n from items where run_id=$1 group by state", [runId]);
  const states: Record<string, number> = {};
  for (const r of rows.rows) states[r.state] = r.n;
  const nonterminal = Object.entries(states)
    .filter(([s]) => !TERMINAL_STATES.includes(s))
    .reduce((a, [, n]) => a + n, 0);
  return { ...run.rows[0], states, nonterminal, terminal: nonterminal === 0 };
}

async function main() {
  switch (cmd) {
    case "corpus": {
      const dir = need("out");
      if (has("verify")) {
        const r = verifyCorpus(dir);
        out(r);
        if (!r.ok) process.exit(1);
        return;
      }
      const size = Number(need("size"));
      if (!(size >= 50 && size <= 500)) fail("--size must be 50..500");
      const m = writeCorpus(dir, Number(need("seed")), size, need("tenant"), has("force"));
      out({ corpus_id: m.corpus_id, out: path.resolve(dir), ...m.arguments, totals: m.totals, edge_cases: m.edge_cases, digest: m.digest });
      return;
    }
    case "stub": {
      const port = Number(flag("port") ?? 8080);
      createStub().listen(port, () => console.log(`stub listening on ${port}`));
      return; // foreground
    }
    case "up":
      out(await up(Number(flag("workers") ?? 4)));
      return;
    case "down":
      out(await down());
      return;
    case "reset": {
      const w = Number(flag("workers") ?? 4);
      await down();
      out({ reset: true, ...(await up(w)) });
      return;
    }
    case "submit":
      out(await submitCorpus(need("corpus"), need("tenant")));
      return;
    case "status":
      out(await runStatus(need("run")));
      return;
    case "item": {
      const r = await db().query(`select ${ITEM_COLS} from items where tenant=$1 and item_id=$2`, [
        need("tenant"),
        need("id"),
      ]);
      if (!r.rowCount) fail("not found");
      out(r.rows[0]);
      return;
    }
    case "items": {
      const tenant = need("tenant");
      const runId = need("run");
      const state = flag("state");
      const run = await db().query("select run_id from runs where run_id=$1 and tenant=$2", [runId, tenant]);
      if (!run.rowCount) fail("not found");
      const r = await db().query(
        `select ${ITEM_COLS} from items where tenant=$1 and run_id=$2 ${state ? "and state=$3" : ""} order by item_id`,
        state ? [tenant, runId, state] : [tenant, runId],
      );
      out(r.rows);
      return;
    }
    case "kill-worker": {
      const idx = flag("index");
      out(await killWorker(idx === undefined ? undefined : Number(idx)));
      return;
    }
    case "workers":
      out(await liveWorkers());
      return;
    case "scenario": {
      const { scenario } = await import("./scenario.js");
      const ok = await scenario();
      await closeDb();
      process.exit(ok ? 0 : 1);
    }
    default:
      console.error(
        `usage: ./intake <corpus|stub|up|down|reset|submit|status|item|items|kill-worker|workers|scenario> [flags]`,
      );
      process.exit(2);
  }
}

main()
  .then(() => closeDb())
  .catch(async (e) => {
    console.error(JSON.stringify({ error: String(e?.message ?? e) }));
    await closeDb().catch(() => {});
    process.exit(1);
  });

// M2 scenario + paired control (section 7).
import fs from "node:fs";
import path from "node:path";
import { db } from "./db.js";
import { POLICY } from "./pipeline.js";
import { ROOT, RUN_DIR, up, killWorker, liveWorkers, truncateState, stubReset, stubStats } from "./env.js";
import { writeCorpus } from "./corpus.js";
import { submitCorpus, runStatus } from "./cli.js";

const PROFILE = {
  corpus_a: { tenant: "tenant-a", seed: 20260803, size: 500, dir: path.join(ROOT, "corpora/tenant-a") },
  corpus_b: { tenant: "tenant-b", seed: 771103, size: 400, dir: path.join(ROOT, "corpora/tenant-b") },
  workers: 4,
  stub: { latency_mode: "fixed", latency_ms: 150, failure_every_n: 7, failure_status: 500, in_flight_capacity: 2 },
  submit_b_when_nonterminal_fraction_at_least: 0.25,
  recovery_budget_ms: 10_000,
  // D-06 secondary thresholds, fixed in advance
  max_annotation_failed_fraction: 0.01,
  max_retry_per_item: 0.35,
  fault_slowdown_allowance: { factor: 1.5, plus_ms: 30_000 },
};
const RAW = path.join(ROOT, "evaluation/raw");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

type Assertion = { id: string; mandatory: boolean; pass: boolean; reason: string };

async function metrics(runId: string) {
  const r = await db().query(
    `select count(*)::int items, coalesce(sum(attempts),0)::int attempts,
            coalesce(sum(retries),0)::int retries, coalesce(sum(annotate_calls),0)::int annotate_calls,
            min(created_at) first_created, max(terminal_at) last_terminal,
            count(annotation)::int annotated_payloads
       from items where run_id=$1`,
    [runId],
  );
  return { ...(await runStatus(runId)), ...r.rows[0] };
}

async function edgeCheck(runId: string, dir: string) {
  const manifest = JSON.parse(fs.readFileSync(path.join(dir, "manifest.json"), "utf8"));
  const problems: string[] = [];
  for (const e of manifest.edge_cases) {
    const r = await db().query("select state, annotation, error from items where run_id=$1 and source_path=$2", [
      runId,
      e.path,
    ]);
    if (!r.rowCount) problems.push(`${e.path}: item missing`);
    else {
      const it = r.rows[0];
      if (it.state !== e.expected_outcome) problems.push(`${e.path}: state ${it.state} != ${e.expected_outcome}`);
      if (it.annotation) problems.push(`${e.path}: annotation present but expects_annotation=false`);
      if (!it.error?.code) problems.push(`${e.path}: no machine-readable error`);
    }
  }
  // no annotation was requested for the edge cases
  const calls = await db().query(
    `select coalesce(sum(annotate_calls),0)::int n from items where run_id=$1 and source_path = any($2::text[])`,
    [runId, manifest.edge_cases.map((e: any) => e.path)],
  );
  if (calls.rows[0].n !== 0) problems.push(`edge cases issued ${calls.rows[0].n} annotation calls`);
  return problems;
}

async function execute(label: "control" | "fault") {
  const kill = label === "fault";
  const log: string[] = [];
  const say = (s: string) => {
    const line = `${new Date().toISOString()} [${label}] ${s}`;
    log.push(line);
    console.log(line);
  };

  // execution isolation: empty pipeline state, fresh workers, stub counters/sequences reset
  await up(PROFILE.workers);
  await truncateState();
  for (const f of fs.existsSync(RUN_DIR) ? fs.readdirSync(RUN_DIR) : []) {
    if (f.endsWith(".log")) fs.truncateSync(path.join(RUN_DIR, f), 0);
  }
  await stubReset(PROFILE.stub);
  say(`state truncated, stub reset: ${JSON.stringify(PROFILE.stub)}`);

  const started = Date.now();
  const a = await submitCorpus(PROFILE.corpus_a.dir, PROFILE.corpus_a.tenant);
  say(`submitted A run=${a.run_id} tenant=${a.tenant} items=${a.items}`);

  // submit B while >=25% of A is still nonterminal, and A already has a terminal item
  let overlapA: any = null;
  for (;;) {
    const s = await runStatus(a.run_id);
    const frac = s.nonterminal / s.item_count;
    if (s.item_count - s.nonterminal >= 1 && frac >= PROFILE.submit_b_when_nonterminal_fraction_at_least) {
      overlapA = { at: new Date().toISOString(), nonterminal: s.nonterminal, fraction: frac, terminalled: s.item_count - s.nonterminal };
      break;
    }
    if (s.terminal) break;
    await sleep(200);
  }
  const b = await submitCorpus(PROFILE.corpus_b.dir, PROFILE.corpus_b.tenant);
  say(`submitted B run=${b.run_id} tenant=${b.tenant} items=${b.items} (A nonterminal fraction ${overlapA?.fraction?.toFixed(3)})`);

  // both runs must have a terminal item and a nonterminal item at the same moment
  let bothOverlap: any = null;
  for (let i = 0; i < 600 && !bothOverlap; i++) {
    const [sa, sb] = [await runStatus(a.run_id), await runStatus(b.run_id)];
    const ok = (s: any) => s.nonterminal > 0 && s.item_count - s.nonterminal >= 1;
    if (ok(sa) && ok(sb))
      bothOverlap = {
        at: new Date().toISOString(),
        a: { nonterminal: sa.nonterminal, terminal_items: sa.item_count - sa.nonterminal },
        b: { nonterminal: sb.nonterminal, terminal_items: sb.item_count - sb.nonterminal },
      };
    else await sleep(200);
  }
  if (bothOverlap) say(`overlap proven: ${JSON.stringify(bothOverlap)}`);

  let killInfo: any = null;
  let recovery: any = null;
  if (kill) {
    killInfo = await killWorker();
    const killedAt = Date.now();
    say(`killed ${killInfo.killed.worker_id} owning ${killInfo.owned_nonterminal_items.length} nonterminal item(s)`);
    const owned: string[] = killInfo.owned_nonterminal_items.map((i: any) => i.item_id);
    if (owned.length) {
      const seen: Record<string, number> = {};
      for (let i = 0; i < 200 && Object.keys(seen).length < owned.length; i++) {
        const r = await db().query(
          "select item_id, worker_id, state, terminal_at from items where item_id = any($1::text[])",
          [owned],
        );
        for (const it of r.rows) {
          if (seen[it.item_id]) continue;
          if (it.worker_id !== killInfo.killed.worker_id || it.terminal_at) seen[it.item_id] = Date.now() - killedAt;
        }
        if (Object.keys(seen).length < owned.length) await sleep(100);
      }
      recovery = {
        killed_at: killInfo.killed_at,
        owned_items: owned,
        resume_ms_per_item: seen,
        max_resume_ms: Math.max(...Object.values(seen), 0),
        all_resumed: Object.keys(seen).length === owned.length,
      };
      say(`resumed elsewhere: ${JSON.stringify(recovery.resume_ms_per_item)}`);
    }
    const stillLive = await liveWorkers();
    killInfo.live_workers_after = stillLive.map((w) => w.worker_id);
  }

  // drain
  let sa = await runStatus(a.run_id);
  let sb = await runStatus(b.run_id);
  for (let i = 0; i < 3600 && !(sa.terminal && sb.terminal); i++) {
    await sleep(500);
    sa = await runStatus(a.run_id);
    sb = await runStatus(b.run_id);
  }
  const wall_ms = Date.now() - started;
  say(`drained in ${wall_ms}ms; A=${JSON.stringify(sa.states)} B=${JSON.stringify(sb.states)}`);

  const ma = await metrics(a.run_id);
  const mb = await metrics(b.run_id);
  const stats = await stubStats();
  const recordedCalls = ma.annotate_calls + mb.annotate_calls;

  // cross-tenant negative test (REQ-2.3)
  const sample = await db().query("select item_id from items where run_id=$1 limit 1", [a.run_id]);
  const cross = await db().query("select item_id from items where tenant=$1 and item_id=$2", [
    PROFILE.corpus_b.tenant,
    sample.rows[0].item_id,
  ]);
  const crossRunLookup = await db().query("select run_id from runs where run_id=$1 and tenant=$2", [
    a.run_id,
    PROFILE.corpus_b.tenant,
  ]);
  const misattributed = await db().query(
    `select count(*)::int n from items where (run_id=$1 and tenant<>$2) or (run_id=$3 and tenant<>$4)`,
    [a.run_id, PROFILE.corpus_a.tenant, b.run_id, PROFILE.corpus_b.tenant],
  );

  const totalItems = ma.items + mb.items;
  const result = {
    label,
    started_at: new Date(started).toISOString(),
    finished_at: new Date().toISOString(),
    wall_ms,
    items_per_second: Number((totalItems / (wall_ms / 1000)).toFixed(2)),
    profile: PROFILE,
    policy: POLICY,
    runs: { a: ma, b: mb },
    overlap: { b_submitted_when: overlapA, both_runs_partially_terminal: bothOverlap },
    kill: killInfo,
    recovery,
    stub_stats: stats,
    recorded_annotate_calls: recordedCalls,
    billed_minus_recorded: stats.billed_calls - recordedCalls,
    tenant_isolation: {
      cross_tenant_item_lookup_rows: cross.rowCount,
      cross_tenant_run_lookup_rows: crossRunLookup.rowCount,
      misattributed_items: misattributed.rows[0].n,
    },
    edge_cases: { a: await edgeCheck(a.run_id, PROFILE.corpus_a.dir), b: await edgeCheck(b.run_id, PROFILE.corpus_b.dir) },
    log,
  };

  fs.mkdirSync(RAW, { recursive: true });
  fs.writeFileSync(path.join(RAW, `${label}.json`), JSON.stringify(result, null, 2) + "\n");
  for (const f of fs.readdirSync(RUN_DIR).filter((f) => f.endsWith(".log"))) {
    fs.copyFileSync(path.join(RUN_DIR, f), path.join(RAW, `${label}-${f}`));
  }
  return result;
}

function assertions(control: any, fault: any): Assertion[] {
  const A: Assertion[] = [];
  const add = (id: string, mandatory: boolean, pass: boolean, reason: string) => A.push({ id, mandatory, pass, reason });

  for (const ex of [control, fault]) {
    const l = ex.label;
    const allTerminal = ex.runs.a.terminal && ex.runs.b.terminal;
    add(`REQ-1.1/${l}: every item terminal`, true, allTerminal, `A=${JSON.stringify(ex.runs.a.states)} B=${JSON.stringify(ex.runs.b.states)}`);
    const edge = [...ex.edge_cases.a, ...ex.edge_cases.b];
    add(`CORPUS-REQ-4/${l}: edge cases hit their outcomes without annotation`, true, edge.length === 0, edge.length ? edge.join("; ") : "empty_content + decode_failed exact, 0 annotation calls");
    add(
      `REQ-2.2/${l}: one shared limit (max_in_flight<=2, over_capacity_calls==0)`,
      true,
      ex.stub_stats.max_in_flight <= 2 && ex.stub_stats.over_capacity_calls === 0,
      `max_in_flight=${ex.stub_stats.max_in_flight} over_capacity_calls=${ex.stub_stats.over_capacity_calls}`,
    );
    const expectedErrors = Math.floor(ex.stub_stats.billed_calls / PROFILE.stub.failure_every_n);
    add(
      `REQ-2.2/${l}: counters reconcile with item outcomes`,
      true,
      ex.stub_stats.server_error_calls === expectedErrors &&
        ex.billed_minus_recorded >= 0 &&
        ex.billed_minus_recorded <= (l === "fault" ? PROFILE.stub.in_flight_capacity : 0),
      `billed=${ex.stub_stats.billed_calls} recorded=${ex.recorded_annotate_calls} delta=${ex.billed_minus_recorded} server_errors=${ex.stub_stats.server_error_calls} (expected ${expectedErrors})`,
    );
    const maxCalls = PROFILE.workers * 0 + POLICY.max_attempts;
    const retryOk = ex.runs.a.retries + ex.runs.b.retries <= (ex.runs.a.items + ex.runs.b.items) * maxCalls;
    add(`REQ-2.2/${l}: retries within documented policy (<=${POLICY.max_attempts} attempts per pass)`, true, retryOk, `retries A=${ex.runs.a.retries} B=${ex.runs.b.retries}`);
    add(
      `REQ-2.3/${l}: two tenants overlap on the profile timing`,
      true,
      !!ex.overlap.b_submitted_when && ex.overlap.b_submitted_when.fraction >= 0.25 && !!ex.overlap.both_runs_partially_terminal,
      `B submitted with ${(ex.overlap.b_submitted_when?.fraction ?? 0).toFixed(3)} of A nonterminal; both-partially-terminal observation: ${JSON.stringify(ex.overlap.both_runs_partially_terminal)}`,
    );
    add(
      `REQ-2.3/${l}: attribution + cross-tenant lookups return not found`,
      true,
      ex.tenant_isolation.misattributed_items === 0 &&
        ex.tenant_isolation.cross_tenant_item_lookup_rows === 0 &&
        ex.tenant_isolation.cross_tenant_run_lookup_rows === 0,
      JSON.stringify(ex.tenant_isolation),
    );
    const failedFrac = ((ex.runs.a.states.annotation_failed ?? 0) + (ex.runs.b.states.annotation_failed ?? 0)) / (ex.runs.a.items + ex.runs.b.items);
    add(`D-06/${l}: annotation_failed <= ${PROFILE.max_annotation_failed_fraction * 100}%`, false, failedFrac <= PROFILE.max_annotation_failed_fraction, `annotation_failed fraction ${failedFrac.toFixed(4)}`);
    const retryPerItem = (ex.runs.a.retries + ex.runs.b.retries) / (ex.runs.a.items + ex.runs.b.items);
    add(`D-06/${l}: retry amplification <= ${PROFILE.max_retry_per_item}/item`, false, retryPerItem <= PROFILE.max_retry_per_item, `retries per item ${retryPerItem.toFixed(3)}`);
  }

  add(
    "REQ-2.2/fault: killed worker owned a nonterminal item",
    true,
    (fault.kill?.owned_nonterminal_items?.length ?? 0) > 0,
    `owned=${JSON.stringify(fault.kill?.owned_nonterminal_items ?? [])}`,
  );
  add(
    "REQ-2.2/fault: killed worker stays dead, unreplaced",
    true,
    (fault.kill?.live_workers_after?.length ?? 0) === PROFILE.workers - 1 &&
      !fault.kill?.live_workers_after?.includes(fault.kill?.killed?.worker_id),
    `live after kill: ${JSON.stringify(fault.kill?.live_workers_after)}`,
  );
  add(
    `REQ-2.2/fault: work resumes elsewhere within ${PROFILE.recovery_budget_ms}ms`,
    true,
    !!fault.recovery?.all_resumed && fault.recovery.max_resume_ms <= PROFILE.recovery_budget_ms,
    `max_resume_ms=${fault.recovery?.max_resume_ms} per item ${JSON.stringify(fault.recovery?.resume_ms_per_item)}`,
  );
  add(
    "REQ-2.2/fault: kill landed while both runs had nonterminal items",
    true,
    !!fault.overlap.both_runs_partially_terminal,
    JSON.stringify(fault.overlap.both_runs_partially_terminal),
  );
  const delta = fault.stub_stats.billed_calls - control.stub_stats.billed_calls;
  add(
    "REQ-2.4: billed calls reported for both executions with the delta explained",
    true,
    true,
    `control=${control.stub_stats.billed_calls} fault=${fault.stub_stats.billed_calls} delta=${delta} (fault re-annotates work the killed worker had billed but not durably recorded)`,
  );
  const allowance = control.wall_ms * PROFILE.fault_slowdown_allowance.factor + PROFILE.fault_slowdown_allowance.plus_ms;
  add(
    `D-06: fault wall clock <= control*${PROFILE.fault_slowdown_allowance.factor}+${PROFILE.fault_slowdown_allowance.plus_ms}ms`,
    false,
    fault.wall_ms <= allowance,
    `control=${control.wall_ms}ms fault=${fault.wall_ms}ms allowance=${Math.round(allowance)}ms`,
  );
  return A;
}

export async function scenario() {
  // corpora are regenerated from the recorded (seed, size, tenant) so the profile is reproducible
  for (const c of [PROFILE.corpus_a, PROFILE.corpus_b]) {
    writeCorpus(c.dir, c.seed, c.size, c.tenant, true);
    console.log(`corpus ready: ${c.dir} (seed=${c.seed} size=${c.size} tenant=${c.tenant})`);
  }
  const control = await execute("control");
  const fault = await execute("fault");
  const A = assertions(control, fault);

  console.log("\n=== assertions ===");
  for (const a of A) console.log(`${a.pass ? "PASS" : "FAIL"} ${a.mandatory ? "[mandatory]" : "[secondary]"} ${a.id} :: ${a.reason}`);
  const mandatoryFailed = A.filter((a) => a.mandatory && !a.pass);
  const verdict = mandatoryFailed.length === 0 ? "PASS" : "FAIL";
  console.log(`\nverdict: ${verdict} (${A.filter((a) => a.pass).length}/${A.length} assertions passed, ${mandatoryFailed.length} mandatory failures)`);

  fs.mkdirSync(RAW, { recursive: true });
  fs.writeFileSync(
    path.join(RAW, "scenario.json"),
    JSON.stringify(
      {
        verdict,
        generated_at: new Date().toISOString(),
        profile: PROFILE,
        policy: POLICY,
        assertions: A,
        billed_calls: {
          control: control.stub_stats.billed_calls,
          fault: fault.stub_stats.billed_calls,
          delta: fault.stub_stats.billed_calls - control.stub_stats.billed_calls,
        },
        executions: {
          control: { wall_ms: control.wall_ms, items_per_second: control.items_per_second, runs: control.runs, stub_stats: control.stub_stats },
          fault: { wall_ms: fault.wall_ms, items_per_second: fault.items_per_second, runs: fault.runs, stub_stats: fault.stub_stats, recovery: fault.recovery },
        },
      },
      null,
      2,
    ) + "\n",
  );
  return verdict === "PASS";
}

// Durable state writes/reads shared by the CLI and the scenario harness (D-03).
import fs from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";
import { Manifest } from "./corpus.js";
import { db, initSchema, TERMINAL_STATES } from "./db.js";

export const ITEM_COLS = `item_id, run_id, tenant, corpus_id, state, sha256, bytes, declared_bytes, source_path,
  extension, attempts, retries, annotate_calls, extracted_text, annotation, error, worker_id,
  created_at, updated_at, terminal_at`;

export async function submitCorpus(dir: string, tenant: string) {
  const manifest: Manifest = JSON.parse(fs.readFileSync(path.join(dir, "manifest.json"), "utf8"));
  const runId = `run_${Date.now().toString(36)}${randomBytes(3).toString("hex")}`;
  await initSchema();
  await db().query("insert into runs (run_id, tenant, corpus_id, corpus_dir, item_count) values ($1,$2,$3,$4,$5)", [
    runId,
    tenant,
    manifest.corpus_id,
    path.resolve(dir),
    manifest.files.length,
  ]);
  await db().query(
    `insert into items (item_id, run_id, tenant, corpus_id, source_path, abs_path, extension, declared_bytes, state)
     select t.item_id, $2, $3, $4, t.source_path, t.abs_path, t.extension, t.declared_bytes, 'pending'
       from unnest($1::text[], $5::text[], $6::text[], $7::text[], $8::int[])
         as t(item_id, source_path, abs_path, extension, declared_bytes)`,
    [
      manifest.files.map((f) => `${runId}-i${String(f.order).padStart(4, "0")}`),
      runId,
      tenant,
      manifest.corpus_id,
      manifest.files.map((f) => f.path),
      manifest.files.map((f) => path.resolve(dir, "files", f.path)),
      manifest.files.map((f) => f.extension),
      manifest.files.map((f) => f.bytes),
    ],
  );
  return { run_id: runId, tenant, corpus_id: manifest.corpus_id, items: manifest.files.length };
}

export async function runStatus(runId: string) {
  const run = await db().query("select run_id, tenant, corpus_id, item_count from runs where run_id=$1", [runId]);
  if (!run.rowCount) throw new Error(`run not found: ${runId}`);
  const rows = await db().query("select state, count(*)::int as n from items where run_id=$1 group by state", [runId]);
  const states: Record<string, number> = {};
  for (const r of rows.rows) states[r.state] = r.n;
  const nonterminal = Object.entries(states)
    .filter(([s]) => !TERMINAL_STATES.includes(s))
    .reduce((a, [, n]) => a + n, 0);
  return { ...run.rows[0], states, nonterminal, terminal: nonterminal === 0 };
}

// Unified command interface (section 2a).
import path from "node:path";
import { writeCorpus, verifyCorpus } from "./corpus.js";
import { db, closeDb } from "./db.js";
import { up, down, killWorker, liveWorkers } from "./env.js";
import { createStub } from "./stub.js";
import { ITEM_COLS, submitCorpus, runStatus } from "./store.js";

const argv = process.argv.slice(2);
const cmd = argv[0];

const flag = (name: string) => {
  const i = argv.indexOf(`--${name}`);
  return i >= 0 ? argv[i + 1] : undefined;
};
const has = (name: string) => argv.includes(`--${name}`);
const need = (name: string) => flag(name) ?? fail(`missing --${name}`);
const out = (v: unknown) => console.log(JSON.stringify(v, null, 2));
function fail(msg: string): never {
  console.error(JSON.stringify({ error: msg }));
  process.exit(1);
}

async function main() {
  switch (cmd) {
    case "corpus": {
      const dir = need("out");
      if (has("verify")) {
        const r = verifyCorpus(dir);
        out(r);
        if (!r.ok) process.exit(1);
        return;
      }
      const size = Number(need("size"));
      if (!(size >= 50 && size <= 500)) fail("--size must be 50..500");
      const m = writeCorpus(dir, Number(need("seed")), size, need("tenant"), has("force"));
      out({
        corpus_id: m.corpus_id,
        out: path.resolve(dir),
        ...m.arguments,
        totals: m.totals,
        edge_cases: m.edge_cases,
        digest: m.digest,
      });
      return;
    }
    case "stub": {
      const port = Number(flag("port") ?? 8080);
      createStub().listen(port, () => console.log(`stub listening on ${port}`));
      return; // foreground
    }
    case "up":
      out(await up(Number(flag("workers") ?? 4)));
      return;
    case "down":
      out(await down());
      return;
    case "reset": {
      const w = Number(flag("workers") ?? 4);
      await down();
      out({ reset: true, ...(await up(w)) });
      return;
    }
    case "submit":
      out(await submitCorpus(need("corpus"), need("tenant")));
      return;
    case "status":
      out(await runStatus(need("run")));
      return;
    case "item": {
      const r = await db().query(`select ${ITEM_COLS} from items where tenant=$1 and item_id=$2`, [
        need("tenant"),
        need("id"),
      ]);
      if (!r.rowCount) fail("not found");
      out(r.rows[0]);
      return;
    }
    case "items": {
      const tenant = need("tenant");
      const runId = need("run");
      const state = flag("state");
      const run = await db().query("select run_id from runs where run_id=$1 and tenant=$2", [runId, tenant]);
      if (!run.rowCount) fail("not found");
      const r = await db().query(
        `select ${ITEM_COLS} from items where tenant=$1 and run_id=$2 ${state ? "and state=$3" : ""} order by item_id`,
        state ? [tenant, runId, state] : [tenant, runId],
      );
      out(r.rows);
      return;
    }
    case "kill-worker": {
      const idx = flag("index");
      out(await killWorker(idx === undefined ? undefined : Number(idx)));
      return;
    }
    case "workers":
      out(await liveWorkers());
      return;
    case "scenario": {
      const { scenario } = await import("./scenario.js");
      const ok = await scenario();
      await closeDb();
      process.exit(ok ? 0 : 1);
    }
    default:
      console.error(
        "usage: ./intake <corpus|stub|up|down|reset|submit|status|item|items|kill-worker|workers|scenario> [flags]",
      );
      process.exit(2);
  }
}

main()
  .then(() => closeDb())
  .catch(async (e) => {
    console.error(JSON.stringify({ error: String(e?.message ?? e) }));
    await closeDb().catch(() => {});
    process.exit(1);
  });
